VALUES ('eee25a8d-0635-4d2e-a47f-7eca981e4b2a', 'CTET CDP 25-Question Mock Set', 'A comprehensive 25-questions mock model MCQ set covering CTET CDP syllabus.', @cat_id, '["ccfa9c10-00ec-488e-9929-8b861c8b783e", "39df9470-a9fe-41ed-b63b-759d9687faa0", "50e42aa5-666a-4868-9a50-b30bb4c733b4", "1266892e-0575-4554-928e-754704d4a561", "cb2a93a6-9749-443a-95d7-4b63c69329d0", "53e0c678-38e5-4f20-9aa2-b4b5c92cc5be", "d278d448-8a10-4c8f-8f53-a3cb49dff183", "aec41188-18c8-45ef-a487-c99c9935a70e", "abb3f040-5b7a-4020-8e82-e1ccc76afecb", "96a68163-66e9-40b7-8c47-612cd68ec51b", "c3c5a28d-0428-4a1e-b9dc-cf88b11ac13e", "a4d7c6db-6c44-4c7e-a7b4-758c879ead0e", "67e035cf-df05-404c-a3e0-f19e593377b4", "e6ae368b-afb9-4517-9b8c-870601372a66", "a188dc47-2245-4d7b-87bd-48f5e20f03fc", "387d7322-708a-4e12-8817-bc13951853bd", "55b715cc-c9c2-4c39-b54f-b4676c1131e9", "34404d8e-71da-4ac6-968b-3f3e691ecff4", "eb566690-073f-4503-9a3c-513215c8cbbe", "b66755a3-304f-4a03-bdd8-ec5d991f5ab8", "48fe0c9a-f765-4109-b082-c16e1972ba2e", "1aa2f9d5-877b-462d-86b4-1ddcfb1ea31c", "8291cc6e-1061-4f14-b0b9-451114ab146f", "973022ce-87ea-4456-8d93-a10a3b86bb0d", "87504f5d-ce9b-47cf-91a6-86f2563f6673"]', 30, 25.00, 'published');
